-- Persistent, atomic rate-limit counters for authentication endpoints.
-- Apply after 002_authentication.sql in Neon before deploying the matching code.
create table if not exists public.auth_rate_limits (
  key_hash text primary key,
  window_started_at timestamptz not null default now(),
  attempts integer not null default 0 check (attempts >= 0),
  updated_at timestamptz not null default now()
);

create index if not exists auth_rate_limits_updated_idx
  on public.auth_rate_limits (updated_at);

-- Keys are one-way hashes generated by the application; raw email/IP identifiers are not stored.
